ALTER TABLE public.members ADD COLUMN name text NOT NULL DEFAULT 'Example member';
ALTER TABLE public.projects ADD COLUMN name text NOT NULL DEFAULT 'Example project';
ALTER TABLE public.projects ADD COLUMN key text NOT NULL DEFAULT 'EX';
CREATE TABLE public.statuses(id text PRIMARY KEY,name text NOT NULL,is_done boolean NOT NULL DEFAULT false,sort_order integer NOT NULL DEFAULT 0);
